// ============ HELPER FUNCTION: Get product by ID ============
function getProductById($id) {
    global $allProducts;
    foreach ($allProducts as $p) {
        if ($p['id'] == $id) return $p;
    }
    return $allProducts[0]; // default: first product
}

// ============ HELPER FUNCTION: Get products by category ============
function getProductsByCategory($catSlug, $limit = null) {
    global $allProducts;
    $result = array_filter($allProducts, fn($p) => $p['cat_slug'] === $catSlug);
    $result = array_values($result);
    if ($limit) $result = array_slice($result, 0, $limit);
    return $result;
}

// ============ HELPER FUNCTION: Get featured products ============
function getFeaturedProducts($limit = 8) {
    global $allProducts;
    $featured = array_filter($allProducts, fn($p) => in_array($p['badge'], ['Sale', 'Hot', 'New']));
    return array_slice(array_values($featured), 0, $limit);
}